ruleContent.replaceRegex:
@js:
//去除章节简介与正文重复
if(/^◎/.test(result) ){
chapter = result.match(/◎([\s\S]+?)…*◎/)[1].replace(/\s/g,'');
chapter2=result.match(/◎[\s\S]+?◎([\s\S]+)/)[1].replace(/\s/g,'');

//前十个字相同就删除
num = 10
if(chapter.substring(0,num)==chapter2.substring(0,num)){
	result = result.replace(/◎[\s\S]+?◎/,'')
	}else{result}
}else{result}

ruleExplore.bookList:
@JSon:$..[?(@.novelName)]&&$..[?(@.novelname)]&&$.massage
<js>
if(result){
function remove(a,b){
let delIndexList = a; // 要删除的序列
 if (delIndexList.length !== 0) { 
for (let i = delIndexList.length - 1; i >= 0; i--) { b.splice(delIndexList[i], 1) } 
return b
}
}

if(baseUrl=='https://app-cdn.jjwxc.net/bookstore/getFullPage?channel=bhxs&version=3'||baseUrl.match(/novelfree/)){
list=JSON.parse(src);
for(i in list){
channelName=list[i].channelName;
blist=list[i].data;
if(blist!="undefined"){
for(j in blist){
blist[j].channelName=channelName
}}else{blist.channelName=channelName}

}
if(!baseUrl.match(/novelfree/)){
list=remove([0, 6,11,12,13],list)
}else{
list=remove([1],list)
}
result=JSON.stringify(list);}
else if(baseUrl.match(/signIn|getSearchForKeyWords/)){
result="{signIn:["+src+"]}"
}
else{result=result}
}else{result=""}
</js>
$..[?(@.novelName)]&&$..[?(@.novelname)]&&$.signIn[*]

ruleExplore.intro:
$.novelIntroShort||$.novelintroshort
<js>
free="{{$.freeDate}}";
if(free!=""){
result="限免日期：🗓"+free+"\n"+result
}else{
result=result
}
</js>

ruleSearch.bookList:
class.cytable@tag.tr[1:20]@tag.a[1]||$.items[:20]
<js>
list=result.toArray();
json=[];
for(i in list){
id=String(list[i]).match(/href/)?String(list[i].attr("href")).match(/(\d+)/)[1]:list[i].novelid;
url="http://www.jjwxc.net/onebook.php?novelid="+id;
html=String(java.ajax(url));
java.setContent(html);
J=org.jsoup.Jsoup.parse(html);

des=String(J.select("span[style='color:#F98C4D']").text()).replace(/立意：/,'◎ ').replace(/一句话简介：/,'◎ ')+"◎"+java.getElement("id.novelintro").text();
title=J.select('h1[itemprop="name"]').text();
author=J.select('span[itemprop="author"]').text();
cover=J.select(".noveldefaultimage").attr("src");
cat=String(J.select('a[style="text-decoration:none;color: red;"]').text()).replace(/\s/g,',');
status=J.select('span[itemprop="updataStatus"]').text();
size=String(J.select('span[itemprop="wordCount"]').text()).replace(/字/,'');
n=String(java.getElement('@@id.oneboolt@tag.tr.-2@span').text()).replace(/\n/,'•').replace(/\*最新更新/,'').replace(/(.*?)\[VIP\]/,'🔒$1');
num=java.getElement('@@id.oneboolt@tag.tr.-2@tag.td.0').text();
genre=J.select('[itemprop="genre"]').text().split('-')[1];
json.push({
title:title,
author:author,
cat:status+","+cat+','+genre,
size:size,
url:"http://app-cdn.jjwxc.net/androidapi/novelbasicinfo?novelId="+id,
des:des,
new:String(num+"、"+n).replace(/(\d+、)🔒/,'🔒$1'),
cover:cover
})
}
json
</js>

ruleToc.chapterUrl:
@js:
$=result;
cookie=cookie.getKey("http://m.jjwxc.net","sid");
chapterid=$.chapterid;
vip=$.isvip!='0';

type=$.chaptertype=='1';

if( !type){
if(!vip){
result='https://app.jjwxc.net/androidapi/chapterContent?novelId='+baseUrl.match(/novelId=(\d+)/)[1]+'&chapterId='+chapterid
}else{result="https://app.jjwxc.net/androidapi/chapterContent?novelId="+baseUrl.match(/novelId=(\d+)/)[1]+'&versionCode=191&token='+cookie+'&chapterId='+chapterid}
}else{ result=""}

